const body = $input.item.json.body || {};
const known = ['escalation', 'resolved', 'knowledge_approved'];
if (!known.includes(body.event)) return [{ json: { skipped: true, event: body.event || null } }];
const templates = { escalation: 'A conversation needs human support.', resolved: 'A support conversation has been resolved.', knowledge_approved: 'A reviewed knowledge entry has been approved.' };
return [{ json: { event: body.event, conversationId: body.conversationId || null, knowledgeId: body.knowledgeId || null, message: templates[body.event], reason: body.reason || null, sent: false, note: 'Prepared payload. Attach your authenticated notification provider before delivery.' } }];
